/**
 * Period arithmetic shared by the renewal job and the mid-period proration in
 * `updateSeats` / `changePlan`.
 *
 * A monthly period ends on the same day of the following month at the same
 * time of day, or that month's last day when it has none (31 Jan → 28 Feb).
 * An annual period ends on the same day and month a year later (29 Feb → 28
 * Feb). Advancing again always starts from the previous end, so a clamped day
 * carries forward rather than snapping back (28 Feb → 28 Mar).
 */
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const DAY_MS = 24 * 60 * 60 * 1000;

/** 1 for monthly, 12 for annual — the multiplier on the per-seat monthly price. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** Adds `months` calendar months to `date`, clamping the day to the target month's length. */
function addMonthsClamped(date: Date, months: number): Date {
  const day = date.getUTCDate();
  const hours = date.getUTCHours();
  const minutes = date.getUTCMinutes();
  const seconds = date.getUTCSeconds();
  const ms = date.getUTCMilliseconds();

  const firstOfTarget = new Date(
    Date.UTC(
      date.getUTCFullYear(),
      date.getUTCMonth() + months,
      1,
      hours,
      minutes,
      seconds,
      ms,
    ),
  );

  const targetYear = firstOfTarget.getUTCFullYear();
  const targetMonth = firstOfTarget.getUTCMonth();
  const lastDayOfTargetMonth = new Date(
    Date.UTC(targetYear, targetMonth + 1, 0),
  ).getUTCDate();

  return new Date(
    Date.UTC(
      targetYear,
      targetMonth,
      Math.min(day, lastDayOfTargetMonth),
      hours,
      minutes,
      seconds,
      ms,
    ),
  );
}

/** The end of the next period starting at `periodStart`. */
export function addInterval(periodStart: Date, interval: BillingInterval): Date {
  return addMonthsClamped(periodStart, monthsInInterval(interval));
}

/** One elapsed period, advanced from `periodEnd`: the new start is the old end. */
export function nextPeriod(
  periodEnd: IsoTimestamp,
  interval: BillingInterval,
): { start: IsoTimestamp; end: IsoTimestamp } {
  const start = new Date(periodEnd);
  const end = addInterval(start, interval);
  return { start: toIsoTimestamp(start), end: toIsoTimestamp(end) };
}

/** Whole days between two instants, rounded, never less than one. */
export function daysInPeriod(start: IsoTimestamp, end: IsoTimestamp): number {
  const ms = new Date(end).getTime() - new Date(start).getTime();
  return Math.max(1, Math.round(ms / DAY_MS));
}

/**
 * Whole-or-started days remaining from `now` to `periodEnd` — 14 days and 22
 * hours left counts as 15; zero once the period end has been reached.
 */
export function daysLeftInPeriod(now: Date, periodEnd: IsoTimestamp): number {
  const ms = new Date(periodEnd).getTime() - now.getTime();
  if (ms <= 0) return 0;
  return Math.ceil(ms / DAY_MS);
}

/** The full charge for one period: monthly price per seat × seats × months in the period. */
export function fullPeriodChargeCents(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsInInterval(interval);
}

/** A full-period amount scaled by the days left over the days in the period, rounded down. */
export function prorateCents(
  fullChargeCents: number,
  daysLeft: number,
  totalDaysInPeriod: number,
): number {
  if (daysLeft <= 0) return 0;
  return Math.floor((fullChargeCents * daysLeft) / totalDaysInPeriod);
}

