/**
 * Rolls subscriptions whose period has ended onto their next period, invoicing
 * every renewed paid period, and ends cancellations whose date has arrived.
 *
 * Must call (do not reimplement): emit, addInterval, fullPeriodChargeCents, issueInvoice
 */
import { getPlanLimits } from "@/config/plan-limits";
import { addInterval, fullPeriodChargeCents } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { IsoTimestamp } from "@/types/common";

const logger = createLogger("billing-renewal-job");

/**
 * A subscription that is several intervals behind gets one new period per
 * elapsed interval, each invoiced (if paid) at the seat count at that moment,
 * until its period end lies after `now`. A canceled subscription whose
 * cancellation date has arrived moves to the free plan as of that date, with
 * a fresh monthly period and no invoice.
 *
 * Replay-safe: once a subscription's period end is past `now` (or a
 * cancellation has already been applied) it no longer matches either query,
 * so running the job again at the same instant is a no-op for it.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const stamp = toIsoTimestamp(now);

    const renewable = await subscriptionRepo.listRenewable(stamp);
    for (const subscription of renewable) {
      const orgId = subscription.orgId;
      let periodStart: IsoTimestamp = subscription.currentPeriodStart;
      let periodEnd: IsoTimestamp = subscription.currentPeriodEnd;

      while (new Date(periodEnd).getTime() <= now.getTime()) {
        const newStart = periodEnd;
        const newEnd = toIsoTimestamp(
          addInterval(new Date(newStart), subscription.interval),
        );

