379	  actor: Actor,
380	  orgId: OrgId,
381	): Promise<readonly Invoice[]> {
382	  assertOrgScope(actor, orgId);
383	  assertCan(actor, "org:manage_billing", billingResource(orgId));
384	  return invoiceRepo.listInvoices(orgId);
385	}
386	
387	/**
388	 * The subscription row is the authority on which plan an org is on; the
389	 * denormalised `organizations.plan` column is only a display convenience, so
390	 * every quota decision reads the subscription first.
391	 */
392	async function planFor(orgId: OrgId): Promise<PlanId> {
393	  const subscription = await subscriptionRepo.findSubscription(orgId);
394	  if (subscription) return subscription.plan;
395	
396	  const org = requireFound(
397	    await orgRepo.findOrgById(orgId),
398	    "Organization",
399	    orgId,
400	  );
401	  return org.plan;
402	}
403	
404	/** Maps a quota dimension onto the counter that measures it. */
405	async function usageFor(
406	  orgId: OrgId,
407	  resource: LimitedResource,
408	): Promise<number> {
409	  const usage = await usageRepo.getUsage(orgId);
410	
411	  switch (resource) {
412	    case "seats":
413	      return usage.seatsUsed;
414	    case "projects":
415	      return usage.projectsUsed;
416	    case "issuesPerProject":
417	      return usage.issuesUsed;
418	    case "storageMb":
419	      return usage.storageMbUsed;
420	    case "webhooks":
421	      return webhookRepo.countEndpoints(orgId);
422	    case "apiRequestsPerHour":
423	      return 0;
424	  }
425	}
