/**
 * Plan changes and quota arithmetic. The single reader of `PLAN_LIMITS` on the server; every other layer asks this service.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, getPlanLimits, wouldExceedLimit, getLimit
 */
import {
  addInterval,
  daysInPeriod,
  daysLeftInPeriod,
  fullPeriodChargeCents,
  prorateCents,
} from "@/lib/billing-period";
import {
  getLimit,
  getPlanLimits,
  wouldExceedLimit,
} from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, billingResource, requireFound } from "./_support";
import type {
  CancelSubscriptionInput,
  ChangePlanInput,
  UpdateSeatsInput,
} from "@/schemas/billing";
import type {
  BillingSummary,
  Invoice,
  LimitCheck,
  LimitedResource,
  PlanId,
  Subscription,
} from "@/types/billing";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The dimensions the billing page shows a meter for. */
const SUMMARY_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function getBillingSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<BillingSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(orgId),
    "Subscription",
    orgId,
  );

  const checks = await Promise.all(
    SUMMARY_RESOURCES.map((resource) => checkLimit(orgId, resource, 0)),
  );

  const limits = getPlanLimits(subscription.plan);

  return {
    orgId,
    subscription,
    checks,
    upcomingInvoiceCents:
      limits.priceCentsPerSeatMonthly *
      subscription.seats *
      (subscription.interval === "annual" ? 12 : 1),
  };
}

/**
 * The one place a quota is evaluated. Every guard elsewhere calls this rather
 * than reading `PLAN_LIMITS` itself, so a new plan dimension needs changing in
 * exactly two files: `plan-limits.ts` and `usageFor()` below.
 */
export async function checkLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<LimitCheck> {
  const plan = await planFor(orgId);
  const used = await usageFor(orgId, resource);
  const limit = getLimit(plan, resource);

  return {
    resource,
    plan,
    limit,
    used,
    remaining: Math.max(0, limit - used),
    exceeded: wouldExceedLimit(plan, resource, used, requested),
  };
}

/** Throwing form used by the create paths, and it emits the breach event. */
export async function assertWithinLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<void> {
  const check = await checkLimit(orgId, resource, requested);
  if (!check.exceeded) return;

  await emit("billing.limit_exceeded", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit: check.limit,
    used: check.used,
  });

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 *
 * Mid-period plan swaps are charged: a change between two paid plans while
 * active charges the (positive) price difference per seat, prorated over the
 * days left in the unchanged current period; a downgrade or unchanged plan
 * charges nothing. A plan chosen during a trial charges nothing and leaves
 * the trial's period alone. Leaving the free plan for a paid one starts a
 * fresh period right now, invoiced in full; moving to the free plan charges
 * nothing.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const currentPlan = subscription.plan;

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const now = new Date();
  const updated = await (async (): Promise<Subscription> => {
    if (subscription.status === "trialing") {
      return subscriptionRepo.updatePlan(
        input.orgId,
        input.plan,
        input.interval,
        "trialing",
      );
    }

    if (currentPlan === "free" && input.plan !== "free") {
      const periodStart = toIsoTimestamp(now);
      const periodEnd = toIsoTimestamp(addInterval(now, input.interval));
      const result = await subscriptionRepo.startPaidPeriod(
        input.orgId,
        input.plan,
        input.interval,
        periodStart,
        periodEnd,
      );

      const fullCharge = fullPeriodChargeCents(
        getPlanLimits(input.plan).priceCentsPerSeatMonthly,
        subscription.seats,
        input.interval,
      );
      await issueInvoice(
        input.orgId,
        periodStart,
        periodEnd,
        fullCharge,
        actor.userId,
      );

      return result;
    }

    if (currentPlan !== "free" && input.plan !== "free") {
      const diffPerSeat =
        getPlanLimits(input.plan).priceCentsPerSeatMonthly -
        getPlanLimits(currentPlan).priceCentsPerSeatMonthly;

      if (diffPerSeat > 0) {
        const fullCharge = fullPeriodChargeCents(
          diffPerSeat,
          subscription.seats,
          subscription.interval,
        );
        const amount = prorateAmount(
          fullCharge,
          now,
          subscription.currentPeriodStart,
          subscription.currentPeriodEnd,
        );
        await issueInvoice(
          input.orgId,
          subscription.currentPeriodStart,
          subscription.currentPeriodEnd,
          amount,
          actor.userId,
        );
      }
    }

    return subscriptionRepo.updatePlan(
      input.orgId,
      input.plan,
      input.interval,
      "active",
    );
  })();

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  return updated;
}

/**
 * Adding seats to a paid, active subscription charges for the seats added,
 * prorated over the days left in the current period. Removing seats, and any
 * seat change on the free plan or during a trial, charges nothing.
 */
export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  if (input.seats > getLimit(subscription.plan, "seats")) {
    throw new Error(
      `Plan ${subscription.plan} tops out at ${getLimit(subscription.plan, "seats")} seats`,
    );
  }

  const seatsAdded = input.seats - subscription.seats;
  const updated = await subscriptionRepo.updateSeatCount(
    input.orgId,
    input.seats,
  );

  if (
    seatsAdded > 0 &&
    subscription.plan !== "free" &&
    subscription.status === "active"
  ) {
    const fullCharge = fullPeriodChargeCents(
      getPlanLimits(subscription.plan).priceCentsPerSeatMonthly,
      seatsAdded,
      subscription.interval,
    );
    const amount = prorateAmount(
      fullCharge,
      new Date(),
      subscription.currentPeriodStart,
      subscription.currentPeriodEnd,
    );
    await issueInvoice(
      input.orgId,
      subscription.currentPeriodStart,
      subscription.currentPeriodEnd,
      amount,
      actor.userId,
    );
  }

  return updated;
}

function prorateAmount(
  fullChargeCents: number,
  now: Date,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): number {
  const totalDays = daysInPeriod(periodStart, periodEnd);
  const daysLeft = daysLeftInPeriod(now, periodEnd);
  return prorateCents(fullChargeCents, daysLeft, totalDays);
}

/**
 * Issues one invoice for a period, unless the charge is zero. Shared by
 * `changePlan`/`updateSeats` (mid-period proration) and the renewal job
 * (full-period charges). `billing.invoice_issued` is what the audit log and
 * the owner notification key off, so emitting it here is the only place that
 * needs to happen.
 */
export async function issueInvoice(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  amountCents: number,
  actorId: UserId | null,
): Promise<Invoice | null> {
  if (amountCents <= 0) return null;

  const number = await invoiceRepo.nextInvoiceNumber(orgId);
  const invoice = await invoiceRepo.insertInvoice(orgId, {
    orgId,
    number,
    amountCents,
    currency: "usd",
    periodStart,
    periodEnd,
    paidAt: null,
  });

  await emit("billing.invoice_issued", {
    orgId,
    actorId,
    occurredAt: toIsoTimestamp(new Date()),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });

  return invoice;
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
 * every quota decision reads the subscription first.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  if (subscription) return subscription.plan;

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  return org.plan;
}

/** Maps a quota dimension onto the counter that measures it. */
async function usageFor(
  orgId: OrgId,
  resource: LimitedResource,
): Promise<number> {
  const usage = await usageRepo.getUsage(orgId);

  switch (resource) {
    case "seats":
      return usage.seatsUsed;
    case "projects":
      return usage.projectsUsed;
    case "issuesPerProject":
      return usage.issuesUsed;
    case "storageMb":
      return usage.storageMbUsed;
    case "webhooks":
      return webhookRepo.countEndpoints(orgId);
    case "apiRequestsPerHour":
      return 0;
  }
}

/**
 * Subscription rows; one active row per organization.
 */
import { and, eq, isNotNull, isNull, lte, ne } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, organizations, subscriptions } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toSubscription } from "./_mappers";
import type { BillingInterval, PlanId, Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TRIAL_DAYS = 14;

export async function findSubscription(
  orgId: OrgId,
): Promise<Subscription | null> {
  const row = getDb()
    .select()
    .from(subscriptions)
    .where(orgPredicate(subscriptions.orgId, orgId))
    .get();
  return row ? toSubscription(row) : null;
}

/** New organizations start on a trial period rather than an active plan. */
export async function insertSubscription(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const periodEnd = toIsoTimestamp(
    new Date(now.getTime() + TRIAL_DAYS * MS_PER_DAY),
  );

  const row = getDb()
    .insert(subscriptions)
    .values({
      id: newId(),
      orgId,
      plan,
      interval,
      status: plan === "free" ? "active" : "trialing",
      seats: 1,
      currentPeriodStart: stamp,
      currentPeriodEnd: periodEnd,
      cancelAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toSubscription(row);
}

/** A plan change ends the trial: the org has made a deliberate choice. */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({ plan, interval, status: "active", updatedAt: stamp })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Advances the period without touching plan, status or seats. */
export async function advancePeriod(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Ends a cancellation: the workspace lands on the free plan with a fresh monthly period. */
export async function endCancellation(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      plan: "free",
      status: "active",
      cancelAt: null,
      interval: "monthly",
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Changes plan and/or interval without moving the period — a mid-period paid⇄paid or paid→free swap, or a trial choosing a plan. */
export async function updatePlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
  status: Subscription["status"],
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ plan, interval, status, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Starts a fresh period now — a workspace leaving the free plan for a paid one. */
export async function startPaidPeriod(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      plan,
      interval,
      status: "active",
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

export async function updateSeatCount(
  orgId: OrgId,
  seats: number,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ seats, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** `cancelAt === null` reactivates a subscription scheduled for cancellation. */
export async function cancelSubscription(
  orgId: OrgId,
  cancelAt: IsoTimestamp | null,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      cancelAt,
      status: cancelAt === null ? "active" : "canceled",
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */
export async function listTrialsEndingBefore(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select()
    .from(subscriptions)
    .where(
      and(
        eq(subscriptions.status, "trialing"),
        isNotNull(subscriptions.currentPeriodEnd),
        lte(subscriptions.currentPeriodEnd, before),
        ne(subscriptions.plan, "free"),
      ),
    )
    .all();

  return rows.map(toSubscription);
}

/**
 * Feeds the billing-renewal job: every active subscription whose period has
 * ended, for workspaces that are not archived. Cross-tenant by design.
 */
export async function listRenewable(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        eq(subscriptions.status, "active"),
        lte(subscriptions.currentPeriodEnd, before),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

/**
 * Feeds the billing-renewal job: every canceled subscription whose
 * cancellation date has arrived, for workspaces that are not archived.
 */
export async function listCancelable(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        eq(subscriptions.status, "canceled"),
        isNotNull(subscriptions.cancelAt),
        lte(subscriptions.cancelAt, before),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

const NOTIFICATION_KINDS = [
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
] as const;

export const notifications = sqliteTable(
  "notifications",
  {
    id: idColumn(),
    ...tenantColumns,
    recipientId: text("recipient_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    href: text("href").notNull(),
    actorId: text("actor_id"),
    readAt: text("read_at"),
    /** JSON array of `NotificationChannel`. */
    channels: text("channels").notNull().default('["in_app"]'),
    ...timestampColumns,
  },
  (table) => [
    index("notifications_org_recipient_idx").on(table.orgId, table.recipientId),
    index("notifications_org_read_idx").on(table.orgId, table.readAt),
  ],
);

export const notificationPreferences = sqliteTable(
  "notification_preferences",
  {
    ...tenantColumns,
    userId: text("user_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    inApp: integer("in_app", { mode: "boolean" }).notNull().default(true),
    email: integer("email", { mode: "boolean" }).notNull().default(true),
    digestOnly: integer("digest_only", { mode: "boolean" })
      .notNull()
      .default(false),
  },
  (table) => [
    uniqueIndex("notification_preferences_pk").on(
      table.orgId,
      table.userId,
      table.kind,
    ),
  ],
);

export type NotificationRow = typeof notifications.$inferSelect;
export type NewNotificationRow = typeof notifications.$inferInsert;
export type NotificationPreferenceRow =
  typeof notificationPreferences.$inferSelect;

